function Invoke-Exp122ContainerStop {
    param([Parameter(Mandatory)][string]$Project,[string[]]$ComposeFiles=@(),[Parameter(Mandatory)][string]$Service,[Parameter(Mandatory)][string]$RunId,[Parameter(Mandatory)][string]$MetadataPath,[int]$GracePeriodSeconds=15,[int]$ProcessTimeoutSeconds=30,[Parameter(Mandatory)][string]$ContainerId,[string]$Executable='docker.exe',[string[]]$ArgumentsOverride=@())
    $before=(docker inspect --format '{{.State.Status}}' $ContainerId).Trim();$started=(Get-Date).ToUniversalTime().ToString('o');$args=if($ArgumentsOverride.Count){$ArgumentsOverride}else{@('compose')+(@($ComposeFiles|ForEach-Object{@('-f',$_)})+@('-p',$Project,'stop','-t',[string]$GracePeriodSeconds,$Service))};$argString=($args|ForEach-Object{if($_ -match '[\s"]'){('"'+($_ -replace '"','\"')+'"')}else{$_}})-join ' '
    $psi=New-Object System.Diagnostics.ProcessStartInfo;$psi.FileName=$Executable;$psi.Arguments=$argString;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$p=New-Object System.Diagnostics.Process;$p.StartInfo=$psi;$null=$p.Start();$stdout=$p.StandardOutput.ReadToEndAsync();$stderr=$p.StandardError.ReadToEndAsync();$timedOut=$false;$attempted=$false;$confirmed=$false;if(-not$p.WaitForExit($ProcessTimeoutSeconds*1000)){$timedOut=$true;$attempted=$true;try{$p.Kill();$p.WaitForExit();$confirmed=$p.HasExited}catch{}};$p.WaitForExit();$p.Refresh();$exit=if($timedOut){$null}else{$p.ExitCode};$after=(docker inspect --format '{{.State.Status}}' $ContainerId).Trim();$completed=(Get-Date).ToUniversalTime().ToString('o');$status=if($timedOut){'APPLICATION_CONTAINER_STOP_TIMEOUT'}elseif($exit-ne0){'APPLICATION_CONTAINER_STOP_FAILED'}elseif($after -match 'running'){'APPLICATION_CONTAINER_STOP_FAILED'}else{'APPLICATION_CONTAINER_STOPPED'};$value=[ordered]@{runId=$RunId;containerId=$ContainerId;command=($Executable+' '+$argString);startedAt=$started;completedAt=$completed;gracePeriodSeconds=$GracePeriodSeconds;processTimeoutSeconds=$ProcessTimeoutSeconds;timedOut=$timedOut;exitCode=$exit;stateBefore=$before;stateAfter=$after;containerStillExists=$true;processTerminationAttempted=$attempted;processTerminationConfirmed=$confirmed;stopStatus=$status;stdout=($stdout.Result);stderr=($stderr.Result)};$value|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $MetadataPath -Encoding UTF8;if($status-ne'APPLICATION_CONTAINER_STOPPED'){throw $status};$value
}


